/**
 * @fileoverview Configuration Loader for Proto-Driven Build System
 * @module config/config-loader
 * 
 * @description
 * Utility for loading processed configuration files from the build directory.
 * These configs are generated by process-configs.sh and contain merged,
 * validated, and environment-substituted configuration data from the proto-driven
 * architecture (77+ proto files → 381 JSON schemas → runtime configs).
 * 
 * This loader bridges the gap between build-time configuration processing and
 * runtime configuration access, providing a consistent interface for all
 * configuration needs throughout the getHarsh ecosystem.
 * 
 * @architecture
 * Configuration loading follows a layered approach:
 * 1. **Proto Layer**: DomainConfig, ThemeConfig, ServicesConfig proto definitions
 * 2. **Processing Layer**: process-configs.sh merges and validates configs
 * 3. **Build Layer**: Configs written to build/configs/[domain]/[mode]/
 * 4. **Runtime Layer**: This loader provides access with caching
 * 5. **Fallback Layer**: Environment variables as last resort
 * 
 * @configuration-files
 * - **config.json**: Main domain configuration (DomainConfig)
 * - **config_services.json**: Services configuration (ServicesConfig)
 * - **theme.json**: Theme configuration (ThemeConfig)
 * - **manifest.json**: Build manifest with metadata
 * 
 * @ecosystem-integration
 * - Gatsby Config: Provides siteMetadata for static generation
 * - React Components: Access via useConfig hook
 * - CMS Integration: Decap CMS configuration generation
 * - Analytics: GTM and consent configuration
 * - Services: Service-specific configurations
 * - Themes: Dynamic theme loading
 * - Search: Index generation configuration
 * 
 * @data-flow
 * 1. Proto schemas define configuration structure
 * 2. YAML configs provide domain-specific values
 * 3. process-configs.sh validates and merges configs
 * 4. Configs written to build directory
 * 5. This loader reads and caches configs
 * 6. Components access via hooks or direct import
 * 
 * @environment-variables
 * - **BUILD_DIR**: Build directory path (default: 'build')
 * - **GATSBY_MODE**: Build mode (LOCAL/PRODUCTION)
 * - **GATSBY_DOMAIN**: Target domain (required)
 * - **WEBSITE_DOMAIN**: Fallback domain
 * - **GATSBY_SERVICES_ENABLED**: Services feature flag
 * 
 * @caching-strategy
 * - In-memory Map for loaded configurations
 * - Cache key: domain-mode-filename
 * - No expiration (configs are static per build)
 * - Manual cache clear available
 * 
 * @error-handling
 * - Missing files: Return null, use fallback
 * - Parse errors: Log warning, return null
 * - Missing domain: Log warning, return null
 * - Graceful degradation to env vars
 * 
 * @dos
 * - Check file existence before reading
 * - Handle JSON parse errors gracefully
 * - Cache loaded configs for performance
 * - Provide type definitions for configs
 * - Use loadConfigWithFallback for resilience
 * - Clear cache in development when configs change
 * 
 * @donts
 * - Don't throw on missing files (use fallback)
 * - Don't modify loaded configuration objects
 * - Don't skip validation in process-configs.sh
 * - Don't hardcode configuration paths
 * - Don't access build directory directly
 * - Don't rely on configs in SSR without checks
 * 
 * @example
 * ```typescript
 * import { 
 *   loadProcessedConfig, 
 *   loadServicesConfig,
 *   loadConfigWithFallback,
 *   areServicesEnabled 
 * } from '@/config/config-loader'
 * 
 * // Load domain configuration
 * const config = loadProcessedConfig()
 * if (config) {
 *   console.log(config.domain_info.title)
 *   console.log(config.theme.theme_id)
 * }
 * 
 * // Load with fallback to env vars
 * const safeConfig = loadConfigWithFallback()
 * console.log(safeConfig.domain_info.domain) // Always available
 * 
 * // Check services
 * if (areServicesEnabled()) {
 *   const servicesConfig = loadServicesConfig()
 *   console.log(servicesConfig?.services)
 * }
 * 
 * // Clear cache in development
 * if (process.env.NODE_ENV === 'development') {
 *   clearConfigCache()
 * }
 * ```
 * 
 * @see {@link file://./BUILD.md#configuration} - Configuration build process
 * @see {@link file://./CMS.md#configuration} - CMS configuration generation
 * @see {@link file://./SERVICES.md#configuration} - Services configuration
 * @see {@link file://./src/hooks/useConfig.ts} - React hook for config access
 * @see {@link file://./config/tools/process-configs.sh} - Config processing script
 * @see {@link file://./config/schema/domain.proto} - DomainConfig proto schema
 * @see {@link file://./gatsby-config.ts} - Gatsby configuration usage
 * 
 * @since 1.0.0
 */

import * as fs from 'fs'
import * as path from 'path'

/**
 * Cache for loaded configurations to avoid repeated file reads.
 * Key format: domain-mode-filename
 */
const configCache: Map<string, any> = new Map()

/**
 * Get the build directory path.
 * Handles both absolute and relative paths.
 * 
 * @returns Absolute path to build directory
 */
const getBuildDir = (): string => {
  const buildDir = process.env.BUILD_DIR || 'build'
  // Handle relative paths from src directory
  return path.isAbsolute(buildDir) 
    ? buildDir 
    : path.join(process.cwd(), '..', buildDir)
}

/**
 * Get current domain from environment.
 * Checks multiple environment variables for compatibility.
 * 
 * @returns Domain name or null if not set
 */
const getCurrentDomain = (): string | null => {
  return process.env.GATSBY_DOMAIN || process.env.WEBSITE_DOMAIN || null
}

/**
 * Get current build mode.
 * Defaults to LOCAL for development safety.
 * 
 * @returns Build mode (LOCAL or PRODUCTION)
 */
const getCurrentMode = (): string => {
  return process.env.GATSBY_MODE || process.env.WEBSITE_MODE || 'LOCAL'
}

/**
 * Load a configuration file from the build directory.
 * Implements caching and error handling.
 * 
 * @param filename - Name of the config file (e.g., 'config.json')
 * @returns Parsed configuration object or null if not found
 */
const loadConfigFile = (filename: string): any | null => {
  const cacheKey = `${getCurrentDomain()}-${getCurrentMode()}-${filename}`
  
  // Check cache first
  if (configCache.has(cacheKey)) {
    return configCache.get(cacheKey)
  }
  
  const domain = getCurrentDomain()
  if (!domain) {
    console.warn('No domain specified, cannot load configuration')
    return null
  }
  
  const mode = getCurrentMode()
  const buildDir = getBuildDir()
  const configPath = path.join(buildDir, 'configs', domain, mode, filename)
  
  try {
    if (fs.existsSync(configPath)) {
      const configContent = fs.readFileSync(configPath, 'utf8')
      const config = JSON.parse(configContent)
      
      // Cache the loaded config
      configCache.set(cacheKey, config)
      
      return config
    }
  } catch (error) {
    console.warn(`Failed to load config from ${configPath}:`, error)
  }
  
  return null
}

/**
 * Load the main processed domain configuration.
 * This includes domain_info, theme, features, consent, and policy settings.
 * Generated from DomainConfig proto schema.
 * 
 * @returns Processed domain configuration or null
 */
export const loadProcessedConfig = (): any | null => {
  return loadConfigFile('config.json')
}

/**
 * Load the services configuration if it exists.
 * Only present for domains with services_enabled: true.
 * Generated from ServicesConfig proto schema.
 * 
 * @returns Processed services configuration or null
 */
export const loadServicesConfig = (): any | null => {
  return loadConfigFile('config_services.json')
}

/**
 * Load configuration with environment variable fallback.
 * Provides resilience when processed configs are unavailable.
 * Essential for build-time operations before configs are generated.
 * 
 * @returns Merged configuration object (never null)
 */
export const loadConfigWithFallback = (): any => {
  const processedConfig = loadProcessedConfig()
  
  // If we have processed config, return it
  if (processedConfig) {
    return processedConfig
  }
  
  // Fallback to environment variables (current behavior)
  return {
    domain_info: {
      domain: process.env.GATSBY_DOMAIN || process.env.WEBSITE_DOMAIN,
      title: process.env.WEBSITE_TITLE,
      entity_key: process.env.GATSBY_ENTITY_KEY || process.env.WEBSITE_ENTITY_KEY,
    },
    theme: {
      theme_id: process.env.WEBSITE_THEME_ID,
    },
    features: {
      services_enabled: process.env.GATSBY_SERVICES_ENABLED === 'true',
    },
    consent_settings: {
      enable_consent_banner: process.env.GATSBY_CONSENT_ENABLED === 'true',
      consent_cookie_name: process.env.GATSBY_CONSENT_COOKIE_NAME,
      consent_duration_days: parseInt(process.env.GATSBY_CONSENT_DURATION_DAYS || '365', 10),
    },
    policy_settings: {
      template_variables: {
        ENTITY_LEGAL_NAME: process.env.GATSBY_LEGAL_ENTITY,
        ENTITY_ABBREVIATION: process.env.GATSBY_ENTITY_KEY,
        DATA_CONTROLLER_EMAIL: process.env.GATSBY_DATA_CONTROLLER_EMAIL,
        DPO_CONTACT: process.env.GATSBY_DPO_CONTACT,
        JURISDICTION: process.env.GATSBY_JURISDICTION,
      }
    }
  }
}

/**
 * Clear the configuration cache.
 * Useful for development hot-reload or when configs change.
 * Should be called when switching domains or modes.
 */
export const clearConfigCache = (): void => {
  configCache.clear()
}

/**
 * Check if services are enabled for the current domain.
 * Validates both feature flag and actual services config existence.
 * 
 * @returns True if services are enabled and configured
 */
export const areServicesEnabled = (): boolean => {
  const config = loadProcessedConfig()
  if (config?.features?.services_enabled) {
    const servicesConfig = loadServicesConfig()
    return servicesConfig?.enabled === true
  }
  
  // Fallback to environment variable
  return process.env.GATSBY_SERVICES_ENABLED === 'true'
}